import React, { useEffect, useRef, useState } from "react";
import { Mic, Send, Square } from "lucide-react";
import { sendVoiceMessage } from "../services/api";
import "./Chat.css";

function Chat() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [listening, setListening] = useState(false);
  const [speaking, setSpeaking] = useState(false);
  const [loading, setLoading] = useState(false);

  const messagesEndRef = useRef(null);
  const recognitionRef = useRef(null);

  // Auto scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({
      behavior: "smooth",
    });
  }, [messages]);

  // Voice response
  const speak = (text) => {
    if (!window.speechSynthesis) return;

    window.speechSynthesis.cancel();

    const speech = new SpeechSynthesisUtterance(text);

    speech.lang = "en-US";
    speech.rate = 1;
    speech.pitch = 1;
    speech.volume = 1;

    speech.onstart = () => {
      setSpeaking(true);
    };

    speech.onend = () => {
      setSpeaking(false);
    };

    speech.onerror = () => {
      setSpeaking(false);
    };

    window.speechSynthesis.speak(speech);
  };

  // Stop AI voice
  const stopSpeaking = () => {
    window.speechSynthesis.cancel();
    setSpeaking(false);
  };

  // Send message to backend
  const sendMessage = async (messageText) => {
    const message = messageText.trim();

    if (!message || loading) return;

    // Show user's message immediately
    setMessages((prev) => [
      ...prev,
      {
        sender: "user",
        text: message,
      },
    ]);

    setInput("");
    setLoading(true);

    try {
      // Backend → AI → response
      const data = await sendVoiceMessage(message);

      const aiResponse =
        data.response || "Sorry, I could not understand that.";

      // Show AI response
      setMessages((prev) => [
        ...prev,
        {
          sender: "ai",
          text: aiResponse,
        },
      ]);

      // Immediately speak AI response
      speak(aiResponse);
    } catch (error) {
      console.error("AI response error:", error);

      const errorMessage =
        "Sorry, something went wrong. Please try again.";

      setMessages((prev) => [
        ...prev,
        {
          sender: "ai",
          text: errorMessage,
        },
      ]);

      speak(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  // Microphone
  const startListening = () => {
    const SpeechRecognition =
      window.SpeechRecognition ||
      window.webkitSpeechRecognition;

    if (!SpeechRecognition) {
      alert(
        "Speech recognition is not supported in this browser. Please use Google Chrome."
      );
      return;
    }

    // Stop AI voice if it is speaking
    stopSpeaking();

    const recognition = new SpeechRecognition();

    recognition.lang = "en-US";
    recognition.continuous = false;
    recognition.interimResults = false;

    recognitionRef.current = recognition;

    recognition.onstart = () => {
      setListening(true);
    };

    recognition.onresult = (event) => {
      const spokenText =
        event.results[0][0].transcript;

      // Put recognized text in input
      setInput(spokenText);

      // Immediately send to AI
      sendMessage(spokenText);
    };

    recognition.onerror = (event) => {
      console.error("Speech recognition error:", event.error);
      setListening(false);
    };

    recognition.onend = () => {
      setListening(false);
    };

    recognition.start();
  };

  // Send button
  const handleSend = () => {
    sendMessage(input);
  };

  // Enter key
  const handleKeyDown = (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="chat-page">

      {/* Header */}
      <div className="chat-header">
        <div>
          <h2>AI Voice Assistant</h2>
          <p>
            {listening
              ? "Listening..."
              : speaking
              ? "AI is speaking..."
              : "Ask me anything"}
          </p>
        </div>

        {speaking && (
          <button
            className="stop-speaking"
            onClick={stopSpeaking}
          >
            <Square size={16} />
            Stop
          </button>
        )}
      </div>

      {/* Chat Area */}
      <div className="chat-messages">

        {messages.length === 0 && (
          <div className="welcome-message">
            <div className="welcome-icon">🤖</div>

            <h1>How can I help you?</h1>

            <p>
              Type your question or tap the microphone
              and start speaking.
            </p>
          </div>
        )}

        {messages.map((message, index) => (
          <div
            key={index}
            className={`message-row ${
              message.sender === "user"
                ? "user-row"
                : "ai-row"
            }`}
          >

            {message.sender === "ai" && (
              <div className="ai-avatar">
                AI
              </div>
            )}

            <div
              className={`message ${
                message.sender === "user"
                  ? "user-message"
                  : "ai-message"
              }`}
            >
              {message.text}
            </div>
          </div>
        ))}

        {/* Loading */}
        {loading && (
          <div className="message-row ai-row">
            <div className="ai-avatar">AI</div>

            <div className="ai-message typing">
              <span></span>
              <span></span>
              <span></span>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="chat-input-area">

        <div className="chat-input-box">

          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={
              listening
                ? "Listening..."
                : "Message AI..."
            }
            rows="1"
          />

          {/* Microphone */}
          <button
            className={`mic-button ${
              listening ? "listening" : ""
            }`}
            onClick={startListening}
            disabled={loading}
            title="Speak"
          >
            <Mic size={21} />
          </button>

          {/* Send */}
          <button
            className="send-button"
            onClick={handleSend}
            disabled={!input.trim() || loading}
            title="Send"
          >
            <Send size={20} />
          </button>

        </div>

        <p className="input-note">
          AI can make mistakes. Check important information.
        </p>

      </div>
    </div>
  );
}

export default Chat;
